CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1), json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS vocabularies(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS words(id INTEGER PRIMARY KEY, word TEXT NOT NULL COLLATE NOCASE UNIQUE, zh TEXT NOT NULL DEFAULT '', en TEXT NOT NULL DEFAULT '', phonetic TEXT NOT NULL DEFAULT '', pos TEXT NOT NULL DEFAULT '', example TEXT NOT NULL DEFAULT '', translation TEXT NOT NULL DEFAULT '', tags TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS vocabulary_words(vocabulary_id INTEGER REFERENCES vocabularies ON DELETE CASCADE, word_id INTEGER REFERENCES words ON DELETE CASCADE, PRIMARY KEY(vocabulary_id,word_id));
CREATE TABLE IF NOT EXISTS cards(word_id INTEGER PRIMARY KEY REFERENCES words ON DELETE CASCADE, json TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 0, due TEXT NOT NULL, reps INTEGER NOT NULL DEFAULT 0, lapses INTEGER NOT NULL DEFAULT 0, state INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS daily_plans(day TEXT PRIMARY KEY, new_goal INTEGER NOT NULL, review_goal INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS study_sessions(id TEXT PRIMARY KEY, day TEXT NOT NULL, seconds INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS review_logs(event_id TEXT PRIMARY KEY, word_id INTEGER REFERENCES words ON DELETE CASCADE, day TEXT NOT NULL, at TEXT NOT NULL, rating INTEGER NOT NULL, is_new INTEGER NOT NULL, seconds INTEGER NOT NULL, mode TEXT NOT NULL, log TEXT NOT NULL, result TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS reviews_day ON review_logs(day);
CREATE INDEX IF NOT EXISTS cards_due ON cards(due);
CREATE TABLE IF NOT EXISTS import_logs(id INTEGER PRIMARY KEY, at TEXT NOT NULL, filename TEXT NOT NULL, json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_generation_cache(key TEXT PRIMARY KEY, content TEXT NOT NULL, at TEXT NOT NULL);
